import {
  type ComponentProps,
  createContext,
  type ReactNode,
  use,
  useCallback,
  useMemo,
} from "react";
import { IconPlaceholder } from "@/components/icon-placeholder";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { NoteEdit } from "@/lib/note-edits";

interface NoteEditMenuContextValue {
  isDisabled: (edit: NoteEdit) => boolean;
  onEdit: (edit: NoteEdit) => void;
}

const NoteEditMenuContext = createContext<NoteEditMenuContextValue | null>(
  null
);

function useNoteEditMenu() {
  const context = use(NoteEditMenuContext);
  if (!context) {
    throw new Error("NoteEditMenu parts must be placed inside a NoteEditMenu.");
  }
  return context;
}

const NEVER_DISABLED = () => false;

interface NoteEditMenuProps {
  children: ReactNode;
  /** Whether an edit can't run now, such as `!canApplyNoteEdit(edit, state)`. */
  disabled?: (edit: NoteEdit) => boolean;
  /** An edit was picked: run it with `applyNoteEdit`. */
  onEdit: (edit: NoteEdit) => void;
}

/**
 * What the items read, without a menu of its own: wrap the content of a menu
 * that opens otherwise, such as a right-click's, so `NoteEditMenuItems` and
 * `NoteEditMenuSub` work in it.
 */
function NoteEditMenuProvider({
  children,
  disabled = NEVER_DISABLED,
  onEdit,
}: NoteEditMenuProps) {
  const value = useMemo(
    () => ({ isDisabled: disabled, onEdit }),
    [disabled, onEdit]
  );
  return <NoteEditMenuContext value={value}>{children}</NoteEditMenuContext>;
}

/** A menu of commands over notes: put `NoteEditMenuItems` and `NoteEditMenuSub` in its content, beside items of your own. */
function NoteEditMenu({ children, ...props }: NoteEditMenuProps) {
  return (
    <NoteEditMenuProvider {...props}>
      <DropdownMenu>{children}</DropdownMenu>
    </NoteEditMenuProvider>
  );
}

/** The button that opens the menu, "Notes" with a caret unless given children. */
function NoteEditMenuTrigger({
  children = "Notes",
  ...props
}: ComponentProps<typeof Button>) {
  return (
    <DropdownMenuTrigger
      render={
        <Button
          data-slot="note-edit-menu-trigger"
          variant="outline"
          {...props}
        />
      }
    >
      {children}
      <IconPlaceholder
        hugeicons="ArrowDown01Icon"
        lucide="ChevronDownIcon"
        phosphor="CaretDownIcon"
        remixicon="RiArrowDownSLine"
        tabler="IconChevronDown"
      />
    </DropdownMenuTrigger>
  );
}

function NoteEditMenuContent({
  align = "end",
  className,
  ...props
}: ComponentProps<typeof DropdownMenuContent>) {
  return (
    <DropdownMenuContent
      align={align}
      className={cn("w-auto min-w-52", className)}
      data-slot="note-edit-menu-content"
      {...props}
    />
  );
}

/** A menu item per edit, with its key beside it. */
function NoteEditMenuItems({ edits }: { edits: readonly NoteEdit[] }) {
  const { isDisabled, onEdit } = useNoteEditMenu();
  const handleClick = useCallback(
    (event: { currentTarget: HTMLElement }) => {
      const item = edits.find(
        (edit) => edit.id === event.currentTarget.dataset.edit
      );
      if (item) {
        onEdit(item);
      }
    },
    [edits, onEdit]
  );
  return edits.map((item) => (
    <DropdownMenuItem
      data-edit={item.id}
      disabled={isDisabled(item)}
      key={item.id}
      onClick={handleClick}
    >
      {item.label}
      {item.shortcut ? (
        <DropdownMenuShortcut>{item.shortcut}</DropdownMenuShortcut>
      ) : null}
    </DropdownMenuItem>
  ));
}

/** A submenu named `label`, holding a menu item per edit. */
function NoteEditMenuSub({
  edits,
  label,
}: {
  edits: readonly NoteEdit[];
  label: ReactNode;
}) {
  return (
    <DropdownMenuSub>
      <DropdownMenuSubTrigger>{label}</DropdownMenuSubTrigger>
      <DropdownMenuSubContent className="w-auto min-w-48">
        <NoteEditMenuItems edits={edits} />
      </DropdownMenuSubContent>
    </DropdownMenuSub>
  );
}

export {
  NoteEditMenu,
  NoteEditMenuContent,
  NoteEditMenuItems,
  NoteEditMenuProvider,
  NoteEditMenuSub,
  NoteEditMenuTrigger,
};

import {
  chopNotes,
  deleteTime,
  duplicateTime,
  fitNotesToScale,
  humanizeNotes,
  insertTime,
  invertNotes,
  joinNotes,
  legatoNotes,
  moveNotes,
  type Note,
  type NoteId,
  quantizeNotes,
  type RollBounds,
  rampVelocity,
  reverseNotes,
  selectionSpan,
  setChance,
  splitNotes,
  stretchNotes,
  toggleMuted,
} from "@audio-ui/core/piano-roll";
import {
  rollScale,
  type Scale,
  scalePitchClasses,
} from "@audio-ui/engine/pitch";

/** What an edit knows of the editor it runs in. */
export interface NoteEditContext {
  /** Where the playhead is, in steps. */
  at: number;
  /** The roll's range: its length, its pitches, and the shortest a note gets from an edit. */
  bounds: RollBounds;
  /** Where the loop ends, in steps: what legato stretches the last notes to. */
  loopEnd: number;
  /** A new id, for each note an edit makes. */
  nextId: () => NoteId;
  /** The scale marked on the roll, which "Fit to scale" needs. */
  scale: Scale | null;
  /** Whether notes are selected, rather than the edit taking every note. */
  selected: boolean;
  /** The grid, in the notes' own time: what Split cuts a selection on and Quantize rounds to. @default 1 */
  step?: number;
}

/** One command over notes: a menu item, and perhaps a key. */
export interface NoteEdit {
  edit: (notes: Note[], ids: Set<NoteId>, context: NoteEditContext) => Note[];
  id: string;
  label: string;
  /** Whether the edit needs a scale marked on the roll. */
  needsScale?: boolean;
  /** Whether the edit works on the time the selection covers, so needs one. */
  needsSelection?: boolean;
  /** The key shown beside the label, such as `⌘E`. */
  shortcut?: string;
}

/** Every line of the grid along a clip: the times a chop to the grid cuts at. */
const gridLines = (duration: number, step = 1) =>
  Array.from({ length: Math.ceil(duration / step) }, (_, line) => line * step);

/** The time the selected notes cover, as a time command reads it. */
const spanOf = (notes: Note[], ids: Set<NoteId>) =>
  selectionSpan(notes, ids) ?? { end: 0, start: 0 };

/** Edits that change when the notes play and how long they last. */
export const TIME_EDITS: NoteEdit[] = [
  {
    // Selected notes chop on the grid; with none, the notes crossing the playhead split there.
    edit: (notes, ids, { at, bounds, nextId, selected, step }) =>
      splitNotes(
        notes,
        ids,
        selected ? gridLines(bounds.duration, step) : at,
        nextId
      ).notes,
    id: "split",
    label: "Split",
    shortcut: "⌘E",
  },
  {
    edit: (notes, ids, { bounds, nextId }) =>
      chopNotes(notes, ids, 2, nextId, bounds.minLength).notes,
    id: "chop",
    label: "Chop in two",
  },
  {
    edit: (notes, ids) => joinNotes(notes, ids),
    id: "join",
    label: "Join",
    shortcut: "⌘J",
  },
  {
    edit: (notes, ids, { bounds, step = 1 }) =>
      quantizeNotes(
        notes,
        ids,
        (time) => Math.round(time / step) * step,
        bounds
      ),
    id: "quantize",
    label: "Quantize",
    shortcut: "⌘U",
  },
  {
    edit: (notes, ids, { bounds, loopEnd }) =>
      legatoNotes(notes, ids, bounds.minLength, loopEnd),
    id: "legato",
    label: "Legato",
  },
  {
    edit: (notes, ids) => reverseNotes(notes, ids),
    id: "reverse",
    label: "Reverse",
  },
  {
    edit: (notes, ids, { bounds }) => stretchNotes(notes, ids, 2, bounds),
    id: "double",
    label: "Twice as long",
  },
  {
    edit: (notes, ids, { bounds }) => stretchNotes(notes, ids, 0.5, bounds),
    id: "half",
    label: "Half as long",
  },
  {
    edit: (notes, ids, { bounds, nextId }) => {
      const { end, start } = spanOf(notes, ids);
      return duplicateTime(notes, start, end, nextId, bounds.duration).notes;
    },
    id: "duplicate-time",
    label: "Duplicate time",
    needsSelection: true,
    shortcut: "⇧⌘D",
  },
  {
    edit: (notes, ids) => {
      const { end, start } = spanOf(notes, ids);
      return deleteTime(notes, start, end);
    },
    id: "delete-time",
    label: "Delete time",
    needsSelection: true,
    shortcut: "⇧⌘⌫",
  },
  {
    edit: (notes, ids, { bounds, nextId }) => {
      const { end, start } = spanOf(notes, ids);
      return insertTime(notes, start, end - start, nextId, bounds.duration);
    },
    id: "insert-time",
    label: "Insert time",
    needsSelection: true,
    shortcut: "⌘I",
  },
];

/** The pitch `steps` steps of `scale` from `pitch`, up for a positive count: a pitch out of the scale goes to the next one in it. */
function scaleStep(pitch: number, scale: Scale, steps: number): number {
  const classes = scalePitchClasses(scale);
  const direction = Math.sign(steps);
  let at = pitch;
  for (let left = Math.abs(steps); left > 0; ) {
    at += direction;
    if (classes.includes(((at % 12) + 12) % 12)) {
      left -= 1;
    }
  }
  return at;
}

/** Moves each note in `ids` a step: of the scale when one is marked, else a semitone. One that would leave the roll stays where it is. */
function stepNotes(
  notes: Note[],
  ids: Set<NoteId>,
  { bounds, scale }: NoteEditContext,
  steps: number
): Note[] {
  if (!scale) {
    return moveNotes(notes, ids, 0, steps, bounds);
  }
  return notes.map((note) => {
    if (!ids.has(note.id)) {
      return note;
    }
    const pitch = scaleStep(note.pitch, scale, steps);
    return pitch < bounds.minPitch || pitch > bounds.maxPitch
      ? note
      : { ...note, pitch };
  });
}

/** Edits that change the notes' pitches: up and down a step (of the scale when one is marked), an octave, inverted, or fitted to the scale. */
export const PITCH_EDITS: NoteEdit[] = [
  {
    edit: (notes, ids, context) => stepNotes(notes, ids, context, 1),
    id: "up",
    label: "Up",
  },
  {
    edit: (notes, ids, context) => stepNotes(notes, ids, context, -1),
    id: "down",
    label: "Down",
  },
  {
    edit: (notes, ids, { bounds }) => moveNotes(notes, ids, 0, 12, bounds),
    id: "octave-up",
    label: "Octave up",
    shortcut: "⇧↑",
  },
  {
    edit: (notes, ids, { bounds }) => moveNotes(notes, ids, 0, -12, bounds),
    id: "octave-down",
    label: "Octave down",
    shortcut: "⇧↓",
  },
  {
    edit: (notes, ids) => invertNotes(notes, ids),
    id: "invert",
    label: "Invert",
  },
  {
    edit: (notes, ids, { bounds, scale }) =>
      scale ? fitNotesToScale(notes, ids, rollScale(scale), bounds) : notes,
    id: "fit",
    label: "Fit to scale",
    needsScale: true,
  },
];

/** Whether and how often the notes play: deactivated stays on the roll, silent. */
export const PLAY_EDITS: NoteEdit[] = [
  {
    edit: (notes, ids) => toggleMuted(notes, ids),
    id: "mute",
    label: "Deactivate",
    shortcut: "0",
  },
  ...[1, 0.75, 0.5, 0.25].map((chance) => ({
    edit: (notes: Note[], ids: Set<NoteId>) => setChance(notes, ids, chance),
    id: `chance-${chance}`,
    label: chance === 1 ? "Always play" : `Play ${chance * 100}% of the time`,
  })),
];

/** Edits that change how hard the notes play. */
export const VELOCITY_EDITS: NoteEdit[] = [
  {
    edit: (notes, ids) => rampVelocity(notes, ids, 0.3, 1),
    id: "crescendo",
    label: "Crescendo",
  },
  {
    edit: (notes, ids) => rampVelocity(notes, ids, 1, 0.3),
    id: "decrescendo",
    label: "Decrescendo",
  },
  {
    edit: (notes, ids, { bounds, step = 1 }) =>
      humanizeNotes(notes, ids, { timing: step / 4, velocity: 0.15 }, bounds),
    id: "humanize",
    label: "Humanize",
  },
];

const ALL_EDITS = [
  ...TIME_EDITS,
  ...PITCH_EDITS,
  ...PLAY_EDITS,
  ...VELOCITY_EDITS,
];
const editById = (id: string) => ALL_EDITS.find((item) => item.id === id);

/** Cmd/Ctrl with a letter: the edits that have a key of their own. */
const EDITS_BY_KEY: Record<string, NoteEdit | undefined> = {
  e: editById("split"),
  i: editById("insert-time"),
  j: editById("join"),
  u: editById("quantize"),
};
/** Cmd/Ctrl + Shift with a key: the time commands. */
const SHIFT_EDITS_BY_KEY: Record<string, NoteEdit | undefined> = {
  backspace: editById("delete-time"),
  d: editById("duplicate-time"),
  delete: editById("delete-time"),
};

/** The edit Cmd/Ctrl (and Shift) with `key` runs, if any. `key` is lower case. */
export function noteEditForKey(
  key: string,
  shiftKey: boolean
): NoteEdit | undefined {
  return shiftKey ? SHIFT_EDITS_BY_KEY[key] : EDITS_BY_KEY[key];
}

/** Whether `edit` can run now: there are notes, and the selection or the scale it needs. */
export function canApplyNoteEdit(
  edit: NoteEdit,
  state: { hasNotes: boolean; hasScale: boolean; hasSelection: boolean }
): boolean {
  return (
    state.hasNotes &&
    (!edit.needsScale || state.hasScale) &&
    (!edit.needsSelection || state.hasSelection)
  );
}

/** Runs `edit` on the selected notes, or on every note with none selected. */
export function applyNoteEdit(
  edit: NoteEdit,
  notes: Note[],
  selection: readonly NoteId[],
  context: Omit<NoteEditContext, "selected">
): Note[] {
  const selected = selection.length > 0;
  const ids = new Set(selected ? selection : notes.map((note) => note.id));
  return edit.edit(notes, ids, { ...context, selected });
}
